public Bitmap enhance(Bitmap bitmap, Filter filter) {
    requireBitmap(bitmap);
    if (filter == null) {
        throw new IllegalArgumentException("Choose a scan filter.");
    }
    Mats mats = new Mats();
    try {
        Mat rgba = boundedRgba(bitmap, 2600, mats);
        if (filter == Filter.ORIGINAL) {
            Bitmap bitmap2 = bitmap(rgba);
            mats.close();
            return bitmap2;
        }
        Mat rgb = mats.add(new Mat());
        Imgproc.cvtColor(rgba, rgb, 1);
        Mat lab = mats.add(new Mat());
        Imgproc.cvtColor(rgb, lab, 45);
        List<Mat> channels = new ArrayList<>(3);
        try {
            Core.split(lab, channels);
            for (Mat channel : channels) {
                mats.add(channel);
            }
            Mat luminance = channels.get(0);
            normalizeLighting(channels, mats);
            if (filter == Filter.AUTO_COLOR) {
                balancePaper(channels);
                Core.merge(channels, lab);
                Imgproc.cvtColor(lab, rgb, 57);
                Bitmap bitmap3 = bitmap(rgb);
                mats.close();
                return bitmap3;
            }
            if (filter == Filter.GRAYSCALE) {
                Bitmap bitmap4 = bitmap(luminance);
                mats.close();
                return bitmap4;
            }
            Mat binary = mats.add(new Mat());
            int block = Math.min(81, Math.min(luminance.cols(), luminance.rows()) / 8);
            Imgproc.adaptiveThreshold(luminance, binary, 255.0d, 1, 0, Math.max(3, block | 1), 12.0d);
            Bitmap bitmap5 = bitmap(binary);
            mats.close();
            return bitmap5;
        } catch (Throwable th) {
            for (Mat channel2 : channels) {
                mats.add(channel2);
            }
            throw th;
        }
    } catch (Throwable th2) {
        try {
            mats.close();
            throw th2;
        } catch (Throwable th3) {
            th2.addSuppressed(th3);
            throw th2;
        }
    }
}
